func newIssue() unsafe.Pointer { return unsafe.Pointer(new(billingqueue.Issue)) }

func newNIssue(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]billingqueue.Issue, n)))
}

func ptrIssue(p unsafe.Pointer, c int32) any {
	r := (*billingqueue.Issue)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ItemID))
	case 4:
		return (*string)(unsafe.Pointer(&r.CheckKey))
	case 5:
		return (*string)(unsafe.Pointer(&r.Code))
	case 6:
		return &r.SubjectKey
	case 7:
		return &r.Summary
	case 8:
		return &r.Reasoning
	case 9:
		return (*string)(unsafe.Pointer(&r.Source))
	case 10:
		return (**string)(unsafe.Pointer(&r.AgentRunID))
	case 11:
		return (**string)(unsafe.Pointer(&r.FlaggedChargeID))
	case 12:
		return &r.Options
	case 13:
		return &r.ResolutionKey
	case 14:
		return &r.ResolutionText
	case 15:
		return &r.EffectSnapshot
	case 16:
		return (**string)(unsafe.Pointer(&r.ResolvedByID))
	case 17:
		return &r.ResolvedAt
	case 18:
		return &r.RequestedAt
	case 19:
		return (**string)(unsafe.Pointer(&r.RequestedByID))
	case 20:
		return &r.Version
	case 21:
		return &r.CreatedAt
	case 22:
		return &r.UpdatedAt
	}
	return nil
}

func valueIssue(p unsafe.Pointer, c int32) any {
	r := (*billingqueue.Issue)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ItemID)
	case 4:
		return string(r.CheckKey)
	case 5:
		return string(r.Code)
	case 6:
		return r.SubjectKey
	case 7:
		return r.Summary
	case 8:
		if r.Reasoning == "" {
			return nil
		}
		return r.Reasoning
	case 9:
		return string(r.Source)
	case 10:
		if r.AgentRunID == nil {
			return nil
		}
		return string(*r.AgentRunID)
	case 11:
		if r.FlaggedChargeID == nil {
			return nil
		}
		return string(*r.FlaggedChargeID)
	case 12:
		if r.Options == nil {
			return keel.EmptyJSONArray
		}
		return r.Options
	case 13:
		if r.ResolutionKey == nil {
			return nil
		}
		return *r.ResolutionKey
	case 14:
		if r.ResolutionText == "" {
			return nil
		}
		return r.ResolutionText
	case 15:
		if r.EffectSnapshot == nil {
			return nil
		}
		return *r.EffectSnapshot
	case 16:
		if r.ResolvedByID == nil {
			return nil
		}
		return string(*r.ResolvedByID)
	case 17:
		if r.ResolvedAt == nil {
			return nil
		}
		return *r.ResolvedAt
	case 18:
		if r.RequestedAt == nil {
			return nil
		}
		return *r.RequestedAt
	case 19:
		if r.RequestedByID == nil {
			return nil
		}
		return string(*r.RequestedByID)
	case 20:
		return r.Version
	case 21:
		return r.CreatedAt
	case 22:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateIssue(ctx context.Context, p unsafe.Pointer) error {
	return (*billingqueue.Issue)(p).BeforeCreate(ctx)
}

